"""Self-contained C.O.R.T.E.X. operations dashboard.

The dashboard is deliberately an operator surface, not a chat mock: it shows
how to start a workflow-agent, its task trace and the agent-toolkit connection
state before the operator presses Run.
"""
from __future__ import annotations


def get_ui_html() -> str:
    return r'''<!doctype html>
<html lang="ru">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>C.O.R.T.E.X. Operations</title>
<style>
:root{--bg:#07111f;--panel:#0e1d31;--line:#23415e;--text:#e8f1fa;--muted:#8fa8bf;--cyan:#55d6f5;--green:#55e39a;--amber:#f6c85f;--red:#ff7185;--purple:#ac91ff;--shadow:0 18px 50px #0005}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% -20%,#19405f 0,#07111f 45%);color:var(--text);font:14px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer;border:1px solid #2f5878;border-radius:8px;background:#173452;color:var(--text);padding:9px 13px}button:hover{background:#204568;border-color:var(--cyan)}button.primary{background:linear-gradient(135deg,#087c99,#155087);border-color:var(--cyan);font-weight:700}.shell{max-width:1480px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:24px}.brand{display:flex;gap:14px;align-items:center}.mark{width:46px;height:46px;border:1px solid var(--cyan);border-radius:14px;display:grid;place-items:center;color:var(--cyan);font-weight:800;font-size:18px;box-shadow:0 0 26px #55d6f533}.eyebrow{color:var(--cyan);font-size:11px;letter-spacing:.18em;text-transform:uppercase}.title{font-size:28px;font-weight:750;letter-spacing:-.03em;margin:2px 0}.subtitle{color:var(--muted)}.status{display:flex;align-items:center;gap:8px;color:var(--muted);border:1px solid var(--line);border-radius:999px;padding:8px 13px;background:#0b1929}.dot{width:8px;height:8px;border-radius:50%;background:var(--green);box-shadow:0 0 10px var(--green)}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:16px}.card{background:linear-gradient(145deg,#10233aee,#0b192aec);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow);padding:18px;min-width:0}.metric{grid-column:span 3}.wide{grid-column:span 8}.side{grid-column:span 4}.full{grid-column:1/-1}.metric h3{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);margin:0 0 12px}.metric .value{font-size:30px;font-weight:750}.metric .hint{color:var(--muted);font-size:12px;margin-top:7px}.card h2{font-size:15px;margin:0 0 14px;display:flex;justify-content:space-between;align-items:center}.tag{font-size:11px;padding:3px 8px;border-radius:99px;background:#173452;color:var(--cyan);font-weight:600}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:13px}.toolbar input,.toolbar select,.toolbar textarea{background:#091727;border:1px solid var(--line);border-radius:8px;padding:9px;color:var(--text);outline:none}.toolbar input:focus,.toolbar select:focus,.toolbar textarea:focus{border-color:var(--cyan)}.toolbar input{min-width:180px;flex:1}.toolbar select{min-width:210px}.toolbar textarea{width:100%;min-height:52px;resize:vertical}.help{color:var(--muted);font-size:12px;margin:-4px 0 13px}.help code,code{color:#bde8ff;background:#091727;border-radius:5px;padding:2px 5px}.notice{grid-column:1/-1;border-radius:12px;padding:13px 16px;border:1px solid #806523;background:#302818;color:#f7d987}.notice strong{color:#ffe8a6}.notice.ok{border-color:#1e654e;background:#102e29;color:#a6efd1}.notice.hidden{display:none}.launch{grid-column:1/-1}.launch-result{border-top:1px solid #1b3650;padding-top:11px;color:var(--muted);font-size:12px;min-height:20px}.launch-result strong{color:var(--text)}.list{max-height:410px;overflow:auto}.row{display:flex;gap:10px;align-items:flex-start;border-top:1px solid #1b3650;padding:11px 0}.row:first-child{border-top:0;padding-top:0}.row .main{flex:1;min-width:0}.name{font-family:ui-monospace,SFMono-Regular,monospace;color:#bde8ff;font-size:12px;word-break:break-all}.desc{color:var(--muted);font-size:12px;margin-top:3px}.badge{white-space:nowrap;font-size:11px;border-radius:99px;padding:3px 7px}.pass{color:var(--green);background:#143c32}.warn{color:var(--amber);background:#47391d}.fail{color:var(--red);background:#4a2631}.skip{color:var(--purple);background:#332951}.event{font-family:ui-monospace,SFMono-Regular,monospace;font-size:11px}.event .type{color:var(--cyan)}.event .time{color:var(--muted);margin-left:7px}.empty{color:var(--muted);padding:25px 0;text-align:center}.bar{height:8px;border-radius:10px;background:#1b334b;overflow:hidden;margin:8px 0 14px}.bar span{display:block;height:100%;background:linear-gradient(90deg,var(--cyan),var(--green));border-radius:inherit;width:0;transition:width .35s}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.summary div{background:#091727;border:1px solid #1a354d;border-radius:9px;padding:10px}.summary b{display:block;font-size:20px}.summary small{color:var(--muted)}pre{margin:0;white-space:pre-wrap;word-break:break-word;color:#b9cde0;font-size:11px;max-height:220px;overflow:auto}.footer{color:#66829b;font-size:11px;text-align:center;padding:22px}.pulse{animation:pulse 2s infinite}@keyframes pulse{50%{opacity:.55}}@media(max-width:1000px){.metric{grid-column:span 6}.wide,.side{grid-column:1/-1}}@media(max-width:600px){.shell{padding:13px}.top{display:block}.status{margin-top:15px;display:inline-flex}.metric{grid-column:1/-1}.summary{grid-template-columns:repeat(2,1fr)}}
</style></head>
<body><main class="shell">
<header class="top"><div class="brand"><div class="mark">CX</div><div><div class="eyebrow">Cognitive Orchestration · Real-time Tactical Execution</div><div class="title">C.O.R.T.E.X. Operations</div><div class="subtitle">Наблюдение и запуск workflow-агентов в реальном времени</div></div></div><div class="status"><span class="dot" id="dot"></span><span id="healthText">connecting…</span></div></header>
<section class="grid">
<div class="card metric"><h3>Runtime</h3><div class="value" id="toolsCount">—</div><div class="hint" id="toolsHint">инструментов в каталоге</div></div>
<div class="card metric"><h3>Event bus</h3><div class="value" id="eventsCount">—</div><div class="hint">событий в журнале</div></div>
<div class="card metric"><h3>Tasks</h3><div class="value" id="tasksCount">—</div><div class="hint">workflow executions</div></div>
<div class="card metric"><h3>Toolkit audit</h3><div class="value" id="coverage">—</div><div class="hint">практическое покрытие</div></div>
<div class="notice hidden" id="connectionNotice"></div>
<div class="card launch"><h2>Запустить агента <span class="tag">workflow gateway</span></h2><div class="help">Это операционная панель, а не чат: кнопка создаёт task, запускает workflow и показывает его trace справа. Первый рекомендуемый запуск — практическая проверка всех инструментов <code>agent_toolkit</code>.</div><div class="toolbar"><input id="agentTitle" value="Agent Toolkit practical audit" aria-label="Название задачи"><select id="agentWorkflow" aria-label="Workflow"><option value="toolkit_audit">Toolkit audit — проверить agent_toolkit</option><option value="context_checkpoint">Context checkpoint — проверить runtime</option></select><button class="primary" onclick="startAgent()">▶ Запустить агента</button><button onclick="runAudit()">Проверить инструменты</button></div><div class="toolbar"><textarea id="agentPayload" placeholder='Payload JSON, например: {"query":"проверить инструменты"}' aria-label="Payload JSON"></textarea></div><div class="launch-result" id="launchResult">Агент не запущен. Выберите workflow и нажмите «Запустить агента».</div></div>
<div class="card wide"><h2>Инструменты <span class="tag" id="providerTag">agent-toolkit</span></h2><div class="toolbar"><input id="search" placeholder="Найти: SQL, антенна, PDF…"><button onclick="loadTools()">Искать</button></div><div class="list" id="tools"><div class="empty pulse">Загрузка каталога…</div></div></div>
<div class="card side"><h2>Последний аудит <span class="tag" id="auditStatus">нет данных</span></h2><div id="auditSummary" class="empty">Аудит ещё не запускался.</div><div class="bar"><span id="auditBar"></span></div><div id="recommendations"></div></div>
<div class="card wide"><h2>Event stream <span class="tag">live SSE</span></h2><div class="list" id="events"><div class="empty">Ожидание событий шины…</div></div></div>
<div class="card side"><h2>Workflows <button onclick="loadTasks()">↻</button></h2><div class="list" id="tasks"><div class="empty">Нет задач</div></div></div>
<div class="card full"><h2>Blackboard / traces <span class="tag">context-preserving</span></h2><pre id="blackboard">Состояние общей доски загружается…</pre></div>
</section><div class="footer">C.O.R.T.E.X. v0.1.0 · local-first runtime · secrets never rendered in UI</div></main>
<script>
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function api(url,options){const r=await fetch(url,options);let data={};try{data=await r.json()}catch(e){data={error:await r.text()}}if(!r.ok)throw Error(data.error||data.detail||'HTTP '+r.status);return data}
function statusBadge(status){const labels={pending:'ожидает',running:'выполняется',completed:'завершён',failed:'ошибка',cancelled:'отменён',waiting_hitl:'нужно согласование'};let c=status==='completed'?'pass':status==='running'?'warn':status==='failed'?'fail':status==='waiting_hitl'?'skip':'warn';return `<span class="badge ${c}">${esc(labels[status]||status)}</span>`}
function setNotice(h){const n=$('connectionNotice');const toolkit=h.toolkit||{};if(toolkit.status==='unavailable'||(h.tools_count??0)<=1){n.className='notice';n.innerHTML='<strong>Agent Toolkit не подключён.</strong> Сейчас доступен только встроенный <code>cortex.fetch</code>. Для запуска первого полезного агента задайте <code>CORTEX_TOOLKIT_MODE=local</code> (sibling-пакет) или <code>CORTEX_TOOLKIT_MODE=remote</code> и <code>MCP_AGENT_TOOLKIT=http://localhost:8090/sse</code>, затем перезапустите сервис.'}else{n.className='notice ok';n.innerHTML='<strong>Agent Toolkit подключён.</strong> Можно запускать audit и другие workflow-агенты.'}}
async function refresh(){try{const h=await api('/health');const toolkit=h.toolkit||{};$('healthText').textContent=`online · ${h.environment||'development'} · toolkit: ${toolkit.status||'unknown'}`;$('toolsCount').textContent=h.tools_count??0;$('toolsHint').textContent=toolkit.status==='ok'?`${toolkit.tools_count||0} agent-toolkit + native`:'только встроенные / провайдер недоступен';$('eventsCount').textContent=h.events_count??0;$('tasksCount').textContent=h.tasks_count??0;setNotice(h);const a=await api('/api/toolkit/audit/latest');if(a&&a.report_id)renderAudit(a);await loadTasks();await loadTools()}catch(e){$('healthText').textContent='offline';$('dot').style.background='var(--red)';$('connectionNotice').className='notice';$('connectionNotice').textContent='Gateway недоступен: '+e.message}}
async function loadTools(){try{const q=$('search').value;const data=await api('/api/tools'+(q?'?q='+encodeURIComponent(q):''));$('providerTag').textContent=data.total?`${data.total} найдено`:'agent-toolkit';$('tools').innerHTML=(data.tools||[]).slice(0,120).map(t=>`<div class="row"><div class="main"><div class="name">${esc(t.name)}</div><div class="desc">${esc(t.description||'')}</div></div>${t.dangerous?'<span class="badge fail">dangerous</span>':''}</div>`).join('')||'<div class="empty">Ничего не найдено. Попробуйте «fetch», «SQL» или «антенна».</div>'}catch(e){$('tools').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function renderAudit(a){const total=a.total||0;const ok=a.success;const status=ok?'completed':(total?'failed':'provider unavailable');$('auditStatus').textContent=status;$('coverage').textContent=(a.tested||0)+'/'+total;$('auditBar').style.width=(total?Math.min(100,(a.tested/total)*100):0)+'%';$('auditSummary').innerHTML=`<div class="summary"><div><b>${a.passed||0}</b><small>работает</small></div><div><b>${a.requires_configuration||0}</b><small>настройка</small></div><div><b>${a.failed||0}</b><small>ошибки</small></div><div><b>${a.skipped||0}</b><small>policy skip</small></div></div>`+(a.notes||[]).slice(0,2).map(note=>`<div class="desc">${esc(note)}</div>`).join('');$('recommendations').innerHTML=(a.recommendations||[]).map(r=>`<div class="row"><div class="main"><span class="badge ${r.priority==='high'?'fail':r.priority==='medium'?'warn':'skip'}">${esc(r.priority)}</span> ${esc(r.text)}</div></div>`).join('')}
function renderLaunchTask(t){$('launchResult').innerHTML=`<strong>${esc(t.title)}</strong> · ${statusBadge(t.status)}<div class="desc">task_id: <code>${esc(t.task_id)}</code> · workflow: ${esc(t.workflow)}</div>${t.error?`<div class="desc" style="color:var(--red)">${esc(t.error)}</div>`:''}`}
async function pollTask(id){for(let i=0;i<40;i++){await sleep(500);try{const t=await api('/api/tasks/'+encodeURIComponent(id));renderLaunchTask(t);if(['completed','failed','cancelled'].includes(t.status)){await loadTasks();await loadBlackboard();const a=await api('/api/toolkit/audit/latest');if(a&&a.report_id)renderAudit(a);return}}catch(e){return}}}
async function startAgent(){let payload={};try{const raw=$('agentPayload').value.trim();if(raw)payload=JSON.parse(raw)}catch(e){$('launchResult').innerHTML='<span style="color:var(--red)">Payload должен быть корректным JSON.</span>';return}try{$('launchResult').textContent='Создаю task…';const d=await api('/api/agent/run',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({title:$('agentTitle').value||'C.O.R.T.E.X. agent task',workflow:$('agentWorkflow').value,payload})});renderLaunchTask(d.task);pollTask(d.task.task_id);await loadTasks()}catch(e){$('launchResult').innerHTML=`<span style="color:var(--red)">${esc(e.message)}</span>`}}
async function runAudit(){ $('agentWorkflow').value='toolkit_audit';$('agentTitle').value='Agent Toolkit practical audit';try{$('launchResult').textContent='Запускаю audit workflow…';const d=await api('/api/toolkit/audit',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({background:true,title:'Agent Toolkit practical audit'})});renderLaunchTask(d.task);pollTask(d.task.task_id)}catch(e){$('launchResult').innerHTML=`<span style="color:var(--red)">${esc(e.message)}</span>`}}
async function loadTasks(){try{const d=await api('/api/tasks');$('tasks').innerHTML=(d.tasks||[]).slice(-10).reverse().map(t=>`<div class="row"><div class="main"><div class="name">${esc(t.title)}</div><div class="desc">${esc(t.task_id.slice(0,8))} · ${esc(t.workflow)}</div></div>${statusBadge(t.status)}</div>`).join('')||'<div class="empty">Нет задач. Нажмите «Запустить агента».</div>'}catch(e){}}
async function loadEvents(){try{const d=await api('/api/events?limit=35');$('events').innerHTML=(d.events||[]).slice().reverse().map(e=>`<div class="row event"><div class="main"><span class="type">${esc(e.event_type)}</span><span class="time">${esc((e.occurred_at||'').slice(11,19))}</span><div class="desc">${esc(e.source)} · ${esc(e.correlation_id||'').slice(0,12)}</div></div></div>`).join('')||'<div class="empty">Нет событий. Запустите workflow.</div>'}catch(e){}}
async function loadBlackboard(){try{$('blackboard').textContent=JSON.stringify(await api('/api/blackboard'),null,2)}catch(e){}}
function refreshLive(){loadEvents();loadTasks();loadBlackboard();refresh()}
function connect(){try{const es=new EventSource('/api/stream');es.onmessage=refreshLive;['task.created','task.running','task.completed','task.failed','toolkit.audit.completed','runtime.tool_hot_swapped'].forEach(name=>es.addEventListener(name,refreshLive));es.onerror=()=>{es.close();setTimeout(connect,4000)}}catch(e){setTimeout(connect,4000)}}
$('search').addEventListener('keydown',e=>{if(e.key==='Enter')loadTools()});refresh();loadEvents();loadBlackboard();connect();setInterval(()=>{loadEvents();loadTasks()},8000);
</script></body></html>'''


__all__ = ["get_ui_html"]
